SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(a),'routine_oid',a.aggfnoid::oid,'routine',to_jsonb(pg_identify_object('pg_proc'::regclass,a.aggfnoid::oid,0)),'functions',(SELECT jsonb_agg(jsonb_build_object('role',x.role,'oid',x.oid,'identity',to_jsonb(pg_identify_object('pg_proc'::regclass,x.oid,0))) ORDER BY x.role) FROM (VALUES ('transition',a.aggtransfn::oid),('final',a.aggfinalfn::oid),('combine',a.aggcombinefn::oid),('serialize',a.aggserialfn::oid),('deserialize',a.aggdeserialfn::oid),('moving_transition',a.aggmtransfn::oid),('moving_inverse',a.aggminvtransfn::oid),('moving_final',a.aggmfinalfn::oid)) x(role,oid) WHERE x.oid<>0),'transition_type',to_jsonb(pg_identify_object('pg_type'::regclass,a.aggtranstype,0)),'moving_type',CASE WHEN a.aggmtranstype<>0 THEN to_jsonb(pg_identify_object('pg_type'::regclass,a.aggmtranstype,0)) END,'sort_operator',CASE WHEN a.aggsortop<>0 THEN to_jsonb(pg_identify_object('pg_operator'::regclass,a.aggsortop,0)) END) ORDER BY a.aggfnoid::oid),'[]'::jsonb) AS payload FROM pg_aggregate a JOIN pg_proc p ON p.oid=a.aggfnoid WHERE p.pronamespace='public'::regnamespace) AS capture